interface CommentsSnapshot {
  schemaVersion: 1;
  items: Comment[];
  contiguousSequence: number;
  resumeCursor: string;
  olderPageCursor?: string;
}

interface SendCommentCommand {
  commandId: string;
  clientCommentId: string;
  body: string;
}

interface CommentsClient {
  getSnapshot(input: {
    streamId: string;
    position: 'latest' | string;
    signal: AbortSignal;
  }): Promise<CommentsSnapshot>;
  subscribe(input: {
    streamId: string;
    resumeCursor: string;
    onEvent: (event: CommentEvent) => void;
    onGap: (afterSequence: number) => void;
  }): () => void;
  send(input: {
    streamId: string;
    command: SendCommentCommand;
    signal: AbortSignal;
  }): Promise<{ acceptedCommandId: string }>;
}
